"""Read-only sync orchestration and deliberately minimal local sync status."""

from __future__ import annotations

from datetime import UTC, datetime
from typing import Any
from sqlalchemy.orm import Session

from ..config import Settings
from ..integrations.graph import GraphClient
from .crypto import EncryptedTokenStore, TokenStoreError
from .graph import fetch_signals, persist_signals


class SyncError(RuntimeError):
    pass


def token_store(settings: Settings) -> EncryptedTokenStore:
    key = settings.app_encryption_key
    if key is None:
        raise SyncError("APP_ENCRYPTION_KEY is not configured")
    return EncryptedTokenStore(settings.token_store_path, key.get_secret_value())


def status(settings: Settings) -> dict[str, Any]:
    configured = not settings.graph_configuration_errors()
    try:
        connected = token_store(settings).load() is not None
    except (SyncError, TokenStoreError):
        connected = False
    return {"configured": configured, "connected": connected, "mode": "read-only", "last_sync_at": None}


def sync(settings: Settings, db: Session | None = None, client: GraphClient | None = None, limit: int = 50) -> dict[str, Any]:
    if settings.graph_configuration_errors():
        raise SyncError("Microsoft Graph is not configured")
    try:
        token = token_store(settings).load()
    except TokenStoreError as error:
        raise SyncError("Stored Graph credentials are unavailable") from error
    if not token or not isinstance(token.get("access_token"), str):
        raise SyncError("Microsoft Graph is not connected")
    graph = client or GraphClient(token["access_token"])
    profile = graph.me()
    if profile.get("id") != settings.microsoft_target_user_id:
        raise SyncError("connected Microsoft user does not match MICROSOFT_TARGET_USER_ID")
    signals = fetch_signals(graph, limit)
    created = persist_signals(db, signals) if db is not None else 0
    return {"mode": "read-only", "synced_at": datetime.now(UTC).isoformat(), "count": len(signals), "new_sources": created}

from pathlib import Path
from urllib.parse import parse_qs, urlparse

from app.config import Settings
from app.integrations.graph import GraphClient
from app.services.crypto import EncryptedTokenStore, generate_encryption_key
from app.services.graph import fetch_signals
from app.services.oauth import authorization_url, verify_state
from app.services.sync import sync


def test_token_store_encrypts_and_tamper_is_rejected(tmp_path: Path) -> None:
    path = tmp_path / "token"
    store = EncryptedTokenStore(path, generate_encryption_key())
    store.save({"access_token": "not-in-cleartext"})
    assert b"not-in-cleartext" not in path.read_bytes()
    path.write_bytes(b"tampered")
    try:
        store.load()
    except Exception as error:
        assert "cannot be decrypted" in str(error)
    else:
        raise AssertionError("tampered token was accepted")


def test_oauth_uses_pkce_and_one_time_state(tmp_path: Path) -> None:
    key = generate_encryption_key()
    settings = Settings(
        microsoft_tenant_id="tenant",
        microsoft_client_id="client",
        microsoft_client_secret="client-secret",
        microsoft_target_user_id="oid",
        app_encryption_key=key,
        oauth_state_store_path=tmp_path / "state",
    )
    query = parse_qs(urlparse(authorization_url(settings)).query)
    assert query["code_challenge_method"] == ["S256"]
    assert verify_state(settings, query["state"][0])
    try:
        verify_state(settings, query["state"][0])
    except Exception:
        pass
    else:
        raise AssertionError("state replay was accepted")


def test_sync_uses_me_and_deduplicates_mocked_messages(tmp_path: Path) -> None:
    key = generate_encryption_key()
    settings = Settings(
        microsoft_tenant_id="tenant", microsoft_client_id="client", microsoft_client_secret="secret",
        microsoft_target_user_id="expected-oid", app_encryption_key=key,
        token_store_path=tmp_path / "tokens",
    )
    EncryptedTokenStore(settings.token_store_path, key).save({"access_token": "token"})
    calls: list[str] = []
    def transport(method: str, url: str, headers: dict[str, str], payload: object) -> dict:
        calls.append(url)
        if "/me?$select=" in url:
            return {"id": "expected-oid"}
        if "/me/mailFolders/" in url:
            return {"value": [{"id": "m1", "subject": "Do task", "bodyPreview": "please", "webLink": "https://x"}, {"id": "m1", "subject": "duplicate"}]}
        if "/me/chats" in url:
            return {"value": [{"id": "chat-1", "topic": "Project"}]}
        if "/chats/chat-1/messages" in url:
            return {"value": [{"id": "t1", "body": {"content": "Follow up"}}]}
        raise AssertionError(url)
    result = sync(settings, client=GraphClient("token", transport))
    assert result["count"] == 2
    assert all("/users/" not in call for call in calls)

"""Normalization boundary between raw Graph responses and local agent intake."""

from __future__ import annotations

from typing import Any
from datetime import datetime

from sqlalchemy import select
from sqlalchemy.orm import Session

from ..integrations.graph import GraphClient
from ..models import Source, SourceKind


def normalize_email(row: dict[str, Any]) -> dict[str, Any]:
    return {"external_id": f"outlook:{row['id']}", "source_kind": "outlook_email", "title": row.get("subject") or "(no subject)", "excerpt": row.get("bodyPreview") or "", "source_url": row.get("webLink"), "observed_at": row.get("receivedDateTime")}


def normalize_teams(row: dict[str, Any]) -> dict[str, Any]:
    body = row.get("body") or {}
    return {"external_id": f"teams:{row['id']}", "source_kind": "teams_message", "title": row.get("chatTopic") or "Teams conversation", "excerpt": body.get("content") if isinstance(body, dict) else str(body), "source_url": row.get("webUrl"), "observed_at": row.get("createdDateTime")}


def fetch_signals(client: GraphClient, limit: int = 50) -> list[dict[str, Any]]:
    rows = [*(normalize_email(row) for row in client.inbox_messages(limit)), *(normalize_teams(row) for row in client.chat_messages(limit))]
    deduped: dict[str, dict[str, Any]] = {}
    for row in rows:
        deduped.setdefault(row["external_id"], row)
    return list(deduped.values())


def persist_signals(db: Session, signals: list[dict[str, Any]]) -> int:
    """Store bounded source metadata idempotently; never persist Graph tokens."""
    created = 0
    for signal in signals:
        external_id = str(signal["external_id"])
        if db.scalar(select(Source.id).where(Source.external_id == external_id)) is not None:
            continue
        observed_at = signal.get("observed_at")
        try:
            parsed_time = datetime.fromisoformat(str(observed_at).replace("Z", "+00:00")) if observed_at else datetime.now()
        except ValueError:
            parsed_time = datetime.now()
        kind = SourceKind(str(signal["source_kind"]))
        db.add(Source(
            kind=kind,
            external_id=external_id,
            subject=str(signal.get("title") or "")[:500] or None,
            url=str(signal.get("source_url") or "")[:2048] or None,
            excerpt=str(signal.get("excerpt") or "")[:2_000] or None,
            observed_at=parsed_time,
        ))
        created += 1
    db.commit()
    return created

